@Composable
fun Screen(show: Boolean) {
    if (show) {
        Header()
    }
    val count = remember { mutableStateOf(0) }
    Counter(count)
}

@Composable
fun ItemList(items: List<Item>) {
    Column {
        for (item in items) {
            ItemRow(item) // remembers its own expanded flag
        }
    }
}

@Composable
fun Sorted(items: ArrayList<String>) {
    val sorted = remember(items) { items.sorted() }
    Text(sorted.joinToString())
}
